// ── claim normalization + similarity ─────────────────────────────────────────

// Function words only — negations and content words carry defect signal.
var STOPWORDS = {
    'the': 1, 'a': 1, 'an': 1, 'and': 1, 'or': 1, 'but': 1, 'if': 1, 'then': 1, 'else': 1,
