// 'ties' (length 4) misses the ies rule and falls through to the es rule.
var STEMMING_RULES = [
    { suffix: 'ies', min: 4, cut: 3, append: 'y' },
    { suffix: 'es', min: 3, cut: 2 },
    { suffix: 's', min: 3, cut: 1 },
    { suffix: 'ing', min: 4, cut: 3 },
    { suffix: 'ed', min: 3, cut: 2 }
