    var severity = severityClassOf(finding && finding.severity);
    var claim = normalizeClaim(claimOf(finding));
    var item = {
        n: registry.next++,
        id: findingIdentity(fileOf(finding), claim, severity),
        file: fileOf(finding),
        claim: claim,
        severity: severity,
        status: STATUS_OPEN,
        raisedRound: round,
        firstSeenAt: at,
        lastSeenAt: at,
        lastLine: lineOf(finding),
        fixHunk: null,
        withdrawReason: null,
        resolvedAt: null,
        history: [historyEntry(round, 'raised')]
